package sprint

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

const (
	maxSharedPromptPrefixBytes = 512 << 10
	sharedSourceReadBuffer     = 32 << 10
)

type promptContextErrorKind string

const (
	promptContextInvalidPath  promptContextErrorKind = "invalid_path"
	promptContextContainment  promptContextErrorKind = "containment"
	promptContextFileKind     promptContextErrorKind = "file_kind"
	promptContextMissing      promptContextErrorKind = "missing_source"
	promptContextInvalidRange promptContextErrorKind = "invalid_range"
	promptContextChanged      promptContextErrorKind = "changed_during_read"
	promptContextEncoding     promptContextErrorKind = "invalid_encoding"
	promptContextBudget       promptContextErrorKind = "budget_exceeded"
)

type promptContextError struct {
	Kind      promptContextErrorKind
	Path      string
	LineRange string
	Allowed   int
	Observed  int
	Unit      string
	Err       error
}

func (e *promptContextError) Error() string {
	location := e.Path
	if e.LineRange != "" {
		location += ":" + e.LineRange
	}
	if location == "" {
		location = "shared prompt context"
	}
	if e.Kind == promptContextBudget {
		unit := e.Unit
		if unit == "" {
			unit = "bytes"
		}
		return fmt.Sprintf("%s: %s (%d %s observed; %d allowed)", e.Kind, location, e.Observed, unit, e.Allowed)
	}
	if e.Err != nil {
		return fmt.Sprintf("%s: %s: %s", e.Kind, location, safePromptContextCause(e.Err))
	}
	return fmt.Sprintf("%s: %s", e.Kind, location)
}

func (e *promptContextError) Unwrap() error { return e.Err }

func safePromptContextCause(err error) string {
	var pathErr *os.PathError
	if errors.As(err, &pathErr) {
		return pathErr.Op + ": " + pathErr.Err.Error()
	}
	return err.Error()
}

type sharedContextReference struct {
	Name, Path, Lines, Symbol, Rationale string
}

type sharedLineRange struct{ Start, End int }

type sharedSourceSelection struct {
	Path       string
	Lines      string
	Ranges     []sharedLineRange
	References []sharedContextReference
}

var codeContextSymbolRE = regexp.MustCompile(`(?im)^\s*-?\s*\*\*Symbol:\*\*\s*` + "`?" + `([^` + "`" + `\r\n]+)` + "`?" + `\s*$`)

func (s Service) prepareSharedPromptContext(ctx context.Context, sp Sprint, inputs PlanningInputs, persistCache bool) (string, error) {
	// Pre-code-context workspaces retain the compatibility behavior established
	// when the stage was introduced. Once the artifact exists, all covered
	// agent-backed operations use the shared renderer and fail closed.
	if inputs.CodeContext == "" {
		return "", nil
	}
	if findings, err := s.codeContextPrerequisite(sp); err != nil {
		if len(findings) > 0 {
			return "", fmt.Errorf("shared prompt code-context prerequisite failed: %s: %w", formatValidationFindings(findings), err)
		}
		return "", fmt.Errorf("shared prompt code-context prerequisite failed: %w", err)
	}
	target, findings := s.resolveSprintTarget(sp, inputs.ProjectIndex, false)
	if len(findings) > 0 {
		return "", fmt.Errorf("resolve shared prompt implementation target: %s", formatValidationFindings(findings))
	}
	if prefix, cacheErr := loadContextPack(s.root, sp, inputs.Requirements, inputs.CodeContext, target.Path); cacheErr == nil {
		return prefix, nil
	}
	prefix, err := renderSharedPromptContext(ctx, sp, inputs.Requirements, inputs.CodeContext, target.Path)
	if err != nil {
		return "", err
	}
	if persistCache {
		// This is a disposable acceleration layer. Failure to write it must not
		// fail, stale, or rerun the governed stage.
		_ = saveContextPack(s.root, sp, inputs.Requirements, inputs.CodeContext, target.Path, prefix, time.Now().UTC())
	}
	return prefix, nil
}

func (s Service) composeSharedPrompt(ctx context.Context, sp Sprint, inputs PlanningInputs, preview PromptPreview) (PromptPreview, error) {
	return s.composeSharedPromptWithCache(ctx, sp, inputs, preview, false)
}

func (s Service) composeSharedRuntimePrompt(ctx context.Context, sp Sprint, inputs PlanningInputs, preview PromptPreview) (PromptPreview, error) {
	return s.composeSharedPromptWithCache(ctx, sp, inputs, preview, true)
}

func (s Service) composeSharedPromptWithCache(ctx context.Context, sp Sprint, inputs PlanningInputs, preview PromptPreview, persistCache bool) (PromptPreview, error) {
	prefix, err := s.prepareSharedPromptContext(ctx, sp, inputs, persistCache)
	if err != nil {
		return PromptPreview{}, err
	}
	preview.Prompt, err = composeStagePromptChecked(prefix, preview.Prompt)
	if err != nil {
		return PromptPreview{}, err
	}
	explanation := explainComposedPrompt(preview.Prompt)
	preview.Explanation = &explanation
	return preview, nil
}

func composeStagePrompt(prefix, suffix string) string {
	if prefix == "" {
		return suffix
	}
	return prefix + suffix
}

func composeStagePromptChecked(prefix, suffix string) (string, error) {
	return composeStagePrompt(prefix, suffix), nil
}

func renderSharedPromptContext(ctx context.Context, sp Sprint, requirements, codeContext, implementationRoot string) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err
	}
	if findings := ValidateCodeContextContent(codeContext); len(findings) > 0 {
		return "", fmt.Errorf("shared prompt code-context artifact failed validation: %s", formatValidationFindings(findings))
	}
	references, err := parseSharedContextReferences(codeContext)
	if err != nil {
		return "", err
	}
	root, err := canonicalImplementationRoot(implementationRoot)
	if err != nil {
		return "", err
	}

	var b strings.Builder
	b.Grow(min(maxSharedPromptPrefixBytes, len(requirements)+len(codeContext)+4096))
	b.WriteString(sharedPromptInstructions)
	fmt.Fprintf(&b, "Project: `%s`\nSprint: `%s`\n", sp.Project, sp.Slug)
	b.WriteString(sharedRequirementsOpen)
	b.WriteString(requirements)
	b.WriteString(sharedRequirementsClose)
	b.WriteString(sharedCodeContextOpen)
	b.WriteString(codeContext)
	b.WriteString(sharedCodeContextClose)
	b.WriteString(sharedSourceEvidenceOpen)
	if err := checkSharedPromptBudget(b.Len(), "", ""); err != nil {
		return "", err
	}
	selections, err := canonicalSharedSelections(references)
	if err != nil {
		return "", err
	}
	for _, selection := range selections {
		if err := ctx.Err(); err != nil {
			return "", err
		}
		available := maxSharedPromptPrefixBytes - b.Len() - len(sharedSourceEvidenceClose) - len(sharedPromptStageBoundary)
		if available < 0 {
			return "", budgetPromptContextError(selection.Path, selection.Lines, maxSharedPromptPrefixBytes, b.Len())
		}
		source, err := readSharedSource(ctx, root, selection.Path, selection.Lines, selection.Ranges, available)
		if err != nil {
			return "", err
		}
		var frame strings.Builder
		fmt.Fprintf(&frame, "\n<<< BEGIN UNTRUSTED TRANSIENT SOURCE EVIDENCE: %s:%s >>>\n", selection.Path, selection.Lines)
		frame.WriteString("Selected entries:")
		for _, ref := range selection.References {
			fmt.Fprintf(&frame, " %s;", ref.Name)
		}
		frame.WriteString("\nSource bytes:\n")
		frame.WriteString(source)
		fmt.Fprintf(&frame, "\n<<< END UNTRUSTED TRANSIENT SOURCE EVIDENCE: %s:%s >>>\n", selection.Path, selection.Lines)
		observed := b.Len() + frame.Len() + len(sharedSourceEvidenceClose) + len(sharedPromptStageBoundary)
		if observed > maxSharedPromptPrefixBytes {
			return "", budgetPromptContextError(selection.Path, selection.Lines, maxSharedPromptPrefixBytes, observed)
		}
		b.WriteString(frame.String())
	}
	b.WriteString(sharedSourceEvidenceClose)
	b.WriteString(sharedPromptStageBoundary)
	if err := checkSharedPromptBudget(b.Len(), "", ""); err != nil {
		return "", err
	}
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return b.String(), nil
}

func canonicalSharedSelections(refs []sharedContextReference) ([]sharedSourceSelection, error) {
	positions := map[string]int{}
	selections := make([]sharedSourceSelection, 0, len(refs))
	for _, ref := range refs {
		ranges, err := parseSharedLineRanges(ref.Path, ref.Lines)
		if err != nil {
			return nil, err
		}
		position, ok := positions[ref.Path]
		if !ok {
			position = len(selections)
			positions[ref.Path] = position
			selections = append(selections, sharedSourceSelection{Path: ref.Path})
		}
		selections[position].Ranges = append(selections[position].Ranges, ranges...)
		selections[position].References = append(selections[position].References, ref)
	}
	for i := range selections {
		ranges := selections[i].Ranges
		sort.Slice(ranges, func(a, b int) bool {
			if ranges[a].Start != ranges[b].Start {
				return ranges[a].Start < ranges[b].Start
			}
			return ranges[a].End < ranges[b].End
		})
		merged := make([]sharedLineRange, 0, len(ranges))
		for _, current := range ranges {
			if len(merged) == 0 || current.Start > merged[len(merged)-1].End+1 {
				merged = append(merged, current)
				continue
			}
			if current.End > merged[len(merged)-1].End {
				merged[len(merged)-1].End = current.End
			}
		}
		selections[i].Ranges = merged
		selections[i].Lines = formatSharedLineRanges(merged)
	}
	return selections, nil
}

func formatSharedLineRanges(ranges []sharedLineRange) string {
	parts := make([]string, 0, len(ranges))
	for _, selected := range ranges {
		if selected.Start == selected.End {
			parts = append(parts, strconv.Itoa(selected.Start))
		} else {
			parts = append(parts, fmt.Sprintf("%d-%d", selected.Start, selected.End))
		}
	}
	return strings.Join(parts, ",")
}

func parseSharedContextReferences(content string) ([]sharedContextReference, error) {
	entries := codeContextEntries(sectionBody(content, "Selected Source References"))
	refs := make([]sharedContextReference, 0, len(entries))
	for _, entry := range entries {
		path := codeContextPathRE.FindStringSubmatch(entry.body)
		lines := codeContextLinesRE.FindStringSubmatch(entry.body)
		reason := codeContextReasonRE.FindStringSubmatch(entry.body)
		if len(path) != 2 || len(lines) != 2 || len(reason) != 2 {
			return nil, &promptContextError{Kind: promptContextInvalidRange, Path: entry.name, Err: errors.New("validated reference fields could not be parsed")}
		}
		ref := sharedContextReference{
			Name:      strings.TrimSpace(entry.name),
			Path:      strings.Trim(strings.TrimSpace(path[1]), "`"),
			Lines:     strings.Trim(strings.TrimSpace(lines[1]), "`"),
			Rationale: strings.TrimSpace(reason[1]),
		}
		if symbol := codeContextSymbolRE.FindStringSubmatch(entry.body); len(symbol) == 2 {
			ref.Symbol = strings.Trim(strings.TrimSpace(symbol[1]), "`")
		}
		refs = append(refs, ref)
	}
	return refs, nil
}

func parseSharedLineRanges(path, value string) ([]sharedLineRange, error) {
	var ranges []sharedLineRange
	for _, segment := range strings.Split(value, ",") {
		segment = strings.TrimSpace(segment)
		parts := strings.Split(segment, "-")
		start, err := strconv.Atoi(strings.TrimSpace(parts[0]))
		if err != nil || start < 1 || len(parts) > 2 {
			return nil, &promptContextError{Kind: promptContextInvalidRange, Path: path, LineRange: value, Err: errors.New("range must be a positive N or N-M")}
		}
		end := start
		if len(parts) == 2 {
			end, err = strconv.Atoi(strings.TrimSpace(parts[1]))
			if err != nil || end < start {
				return nil, &promptContextError{Kind: promptContextInvalidRange, Path: path, LineRange: value, Err: errors.New("range end precedes its start")}
			}
		}
		ranges = append(ranges, sharedLineRange{Start: start, End: end})
	}
	return ranges, nil
}

func canonicalImplementationRoot(root string) (string, error) {
	if root == "" || !filepath.IsAbs(root) {
		return "", &promptContextError{Kind: promptContextContainment, Err: errors.New("implementation root must be absolute")}
	}
	canonical, err := filepath.EvalSymlinks(filepath.Clean(root))
	if err != nil {
		return "", &promptContextError{Kind: promptContextContainment, Err: fmt.Errorf("resolve implementation root: %w", err)}
	}
	info, err := os.Stat(canonical)
	if err != nil {
		return "", &promptContextError{Kind: promptContextContainment, Err: fmt.Errorf("inspect implementation root: %w", err)}
	}
	if !info.IsDir() {
		return "", &promptContextError{Kind: promptContextFileKind, Err: errors.New("implementation root is not a directory")}
	}
	return canonical, nil
}

func readSharedSource(ctx context.Context, root, rel, lineRange string, ranges []sharedLineRange, budget int) (string, error) {
	if err := validateRepositoryRelativePath(rel); err != nil {
		return "", &promptContextError{Kind: promptContextInvalidPath, Path: rel, LineRange: lineRange, Err: err}
	}
	candidate := filepath.Join(root, filepath.FromSlash(rel))
	if !inside(root, candidate) {
		return "", &promptContextError{Kind: promptContextContainment, Path: rel, LineRange: lineRange, Err: errors.New("path escapes implementation root")}
	}
	current := root
	for _, component := range strings.Split(filepath.ToSlash(rel), "/") {
		current = filepath.Join(current, filepath.FromSlash(component))
		info, err := os.Lstat(current)
		if err != nil {
			kind := promptContextMissing
			if !os.IsNotExist(err) {
				kind = promptContextContainment
			}
			return "", &promptContextError{Kind: kind, Path: rel, LineRange: lineRange, Err: err}
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return "", &promptContextError{Kind: promptContextContainment, Path: rel, LineRange: lineRange, Err: errors.New("symlink components are not allowed")}
		}
	}
	canonical, err := filepath.EvalSymlinks(candidate)
	if err != nil || !inside(root, canonical) {
		if err == nil {
			err = errors.New("canonical path escapes implementation root")
		}
		return "", &promptContextError{Kind: promptContextContainment, Path: rel, LineRange: lineRange, Err: err}
	}
	before, err := os.Stat(candidate)
	if err != nil {
		return "", &promptContextError{Kind: promptContextMissing, Path: rel, LineRange: lineRange, Err: err}
	}
	if !before.Mode().IsRegular() {
		return "", &promptContextError{Kind: promptContextFileKind, Path: rel, LineRange: lineRange, Err: errors.New("selected source is not a regular file")}
	}
	f, err := os.Open(candidate)
	if err != nil {
		return "", &promptContextError{Kind: promptContextMissing, Path: rel, LineRange: lineRange, Err: err}
	}
	defer f.Close()
	handleBefore, err := f.Stat()
	if err != nil || !handleBefore.Mode().IsRegular() || !os.SameFile(before, handleBefore) {
		if err == nil {
			err = errors.New("opened source identity does not match the selected path")
		}
		return "", &promptContextError{Kind: promptContextChanged, Path: rel, LineRange: lineRange, Err: err}
	}

	data, totalLines, err := readSharedLineRanges(ctx, f, ranges, budget)
	if err != nil {
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			return "", err
		}
		return "", &promptContextError{Kind: promptContextBudget, Path: rel, LineRange: lineRange, Allowed: budget, Observed: budget + 1, Err: err}
	}
	for _, selected := range ranges {
		if selected.End > totalLines {
			return "", &promptContextError{Kind: promptContextInvalidRange, Path: rel, LineRange: lineRange, Err: fmt.Errorf("range ends at line %d but file has %d lines", selected.End, totalLines)}
		}
	}
	source := string(data)
	if !utf8.ValidString(source) {
		return "", &promptContextError{Kind: promptContextEncoding, Path: rel, LineRange: lineRange, Err: errors.New("selected source is not valid UTF-8")}
	}
	handleAfter, err := f.Stat()
	if err != nil {
		return "", &promptContextError{Kind: promptContextChanged, Path: rel, LineRange: lineRange, Err: err}
	}
	if err := verifySharedSourceUnchanged(root, candidate, canonical, rel, lineRange, handleBefore, handleAfter); err != nil {
		return "", err
	}
	return source, nil
}

func verifySharedSourceUnchanged(root, candidate, canonical, rel, lineRange string, handleBefore, handleAfter os.FileInfo) error {
	after, err := os.Stat(candidate)
	if err != nil || !os.SameFile(handleBefore, handleAfter) || !os.SameFile(handleBefore, after) || handleBefore.Size() != handleAfter.Size() || !handleBefore.ModTime().Equal(handleAfter.ModTime()) {
		if err == nil {
			err = errors.New("selected source changed while it was read")
		}
		return &promptContextError{Kind: promptContextChanged, Path: rel, LineRange: lineRange, Err: err}
	}
	canonicalAfter, err := filepath.EvalSymlinks(candidate)
	if err != nil || canonicalAfter != canonical || !inside(root, canonicalAfter) {
		if err == nil {
			err = errors.New("selected source canonical location changed while it was read")
		}
		return &promptContextError{Kind: promptContextChanged, Path: rel, LineRange: lineRange, Err: err}
	}
	return nil
}

func readSharedLineRange(ctx context.Context, r io.Reader, selected sharedLineRange, budget int) ([]byte, int, error) {
	return readSharedLineRanges(ctx, r, []sharedLineRange{selected}, budget)
}

func readSharedLineRanges(ctx context.Context, r io.Reader, selected []sharedLineRange, budget int) ([]byte, int, error) {
	reader := bufio.NewReaderSize(r, sharedSourceReadBuffer)
	line := 1
	total := 0
	var out []byte
	rangeIndex := 0
	for {
		if err := ctx.Err(); err != nil {
			return nil, 0, err
		}
		fragment, err := reader.ReadSlice('\n')
		if len(fragment) > 0 {
			total = line
			for rangeIndex < len(selected) && line > selected[rangeIndex].End {
				rangeIndex++
			}
			included := rangeIndex < len(selected) && line >= selected[rangeIndex].Start && line <= selected[rangeIndex].End
			if included {
				if len(fragment) > budget-len(out) {
					return nil, 0, errors.New("selected source exceeds remaining shared prompt budget")
				}
				out = append(out, fragment...)
			}
			if fragment[len(fragment)-1] == '\n' {
				line++
			}
		}
		switch err {
		case nil:
			continue
		case bufio.ErrBufferFull:
			continue
		case io.EOF:
			return out, total, nil
		default:
			return nil, 0, err
		}
	}
}

func checkSharedPromptBudget(observed int, path, lineRange string) error {
	if observed <= maxSharedPromptPrefixBytes {
		return nil
	}
	return budgetPromptContextError(path, lineRange, maxSharedPromptPrefixBytes, observed)
}

func budgetPromptContextError(path, lineRange string, allowed, observed int) error {
	return &promptContextError{Kind: promptContextBudget, Path: path, LineRange: lineRange, Allowed: allowed, Observed: observed}
}

package sprint

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"

	pruntime "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

var (
	codeContextHeadingRE = regexp.MustCompile(`(?m)^\s*##\s+(.+?)\s*$`)
	codeContextEntryRE   = regexp.MustCompile(`(?m)^\s*###\s+(.+?)\s*$`)
	codeContextPathRE    = regexp.MustCompile(`(?im)^\s*-?\s*\*\*Path:\*\*\s*` + "`?" + `([^` + "`" + `\r\n]+)` + "`?" + `\s*$`)
	codeContextReasonRE  = regexp.MustCompile(`(?im)^\s*-?\s*\*\*Rationale:\*\*\s*(.+?)\s*$`)
	codeContextLinesRE   = regexp.MustCompile(`(?im)^\s*-?\s*\*\*Lines?:\*\*\s*` + "`?" + `([^` + "`" + `\r\n]+)` + "`?" + `\s*$`)
	codeContextFenceRE   = regexp.MustCompile("(?m)^\\s*```")
	codeContextDriveRE   = regexp.MustCompile(`^[A-Za-z]:`)
)

// Keep the durable context pack below the runtime transport's 96 KiB bounded
// terminal-output limit. This leaves room for provider framing and repair
// diagnostics while allowing a substantial reference catalog without copying
// source into the durable artifact.
const maxCodeContextBytes = 64 << 10

func ValidateCodeContextContent(content string) []ValidationFinding {
	trimmed := strings.TrimSpace(content)
	if trimmed == "" {
		return []ValidationFinding{finding("code-context.md", "", "", "empty code context", "the artifact has no content", "Generate the code-context artifact from validated requirements.")}
	}
	var findings []ValidationFinding
	if len(content) > maxCodeContextBytes {
		findings = append(findings, finding(
			"code-context.md",
			"",
			"",
			"code context exceeds the output budget",
			fmt.Sprintf("the artifact is %d bytes; the maximum is %d bytes", len(content), maxCodeContextBytes),
			"Select fewer source references while retaining the required sections.",
		))
	}
	firstLine := trimmed
	if newline := strings.IndexByte(firstLine, '\n'); newline >= 0 {
		firstLine = firstLine[:newline]
	}
	if strings.TrimSpace(firstLine) != "# Sprint Code Context" {
		findings = append(findings, finding(
			"code-context.md",
			"",
			"",
			"invalid document start",
			"the first non-whitespace line is not the canonical level-one title",
			"Return only the Markdown document beginning with # Sprint Code Context; remove preambles and outer fences.",
		))
	}
	if containsPlaceholder(trimmed) || containsCodeContextPlaceholder(trimmed) {
		findings = append(findings, finding("code-context.md", "", "", "placeholder content", "the artifact still contains template placeholders", "Replace every placeholder with inspected repository evidence."))
		sortSprintFindings(findings)
		return findings
	}
	if codeContextFenceRE.MatchString(trimmed) {
		findings = append(findings, finding("code-context.md", "", "", "embedded source content", "the durable context artifact must contain references rather than copied fenced content", "Remove fenced content and keep source locations as Path, Lines, optional Symbol, and Rationale fields."))
	}
	required := []string{"Sprint Scope", "Inspected Repository Areas", "Selected Source References", "Relationships", "Constraints", "Open Questions"}
	headings := map[string]bool{}
	for _, match := range codeContextHeadingRE.FindAllStringSubmatch(trimmed, -1) {
		headings[strings.ToLower(strings.TrimSpace(match[1]))] = true
	}
	for _, heading := range required {
		if !headings[strings.ToLower(heading)] {
			findings = append(findings, finding(heading, "", "", "missing required section", "the required level-two heading is absent", "Add a ## "+heading+" section with concrete content."))
			continue
		}
		if strings.TrimSpace(sectionBody(trimmed, heading)) == "" {
			findings = append(findings, finding(heading, "", "", "empty required section", "the required section has no content", "Add concrete inspected repository evidence to the section."))
		}
	}
	selected := sectionBody(trimmed, "Selected Source References")
	entries := codeContextEntries(selected)
	if len(entries) == 0 {
		findings = append(findings, finding("Selected Source References", "", "", "no selected source references", "at least one level-three selected entry is required", "Add at least one selected entry with repository-relative path, line range, and rationale."))
	}
	for _, entry := range entries {
		pathMatch := codeContextPathRE.FindStringSubmatch(entry.body)
		if len(pathMatch) != 2 || strings.TrimSpace(pathMatch[1]) == "" {
			findings = append(findings, finding("Selected Source References", entry.name, "", "missing repository-relative path", "the entry has no Path field", "Add **Path:** with a repository-relative source path."))
		} else if err := validateRepositoryRelativePath(strings.TrimSpace(pathMatch[1])); err != nil {
			findings = append(findings, finding("Selected Source References", entry.name, strings.TrimSpace(pathMatch[1]), "unsafe source path", err.Error(), "Use a clean repository-relative path that does not escape the target."))
		}
		reason := codeContextReasonRE.FindStringSubmatch(entry.body)
		if len(reason) != 2 || strings.TrimSpace(reason[1]) == "" {
			findings = append(findings, finding("Selected Source References", entry.name, "", "missing rationale", "the entry does not explain why the reference matters", "Add a concrete **Rationale:** value."))
		}
		if lines := codeContextLinesRE.FindStringSubmatch(entry.body); len(lines) != 2 || strings.TrimSpace(lines[1]) == "" {
			findings = append(findings, finding("Selected Source References", entry.name, "", "missing line range", "the entry has no Lines field", "Add **Lines:** with a positive line number or inclusive range so source can be injected later."))
		} else {
			if err := validateLineRange(strings.TrimSpace(lines[1])); err != nil {
				findings = append(findings, finding("Selected Source References", entry.name, "", "malformed line range", err.Error(), "Use a positive line number or inclusive start-end range."))
			}
		}
	}
	sortSprintFindings(findings)
	return findings
}

func containsCodeContextPlaceholder(content string) bool {
	lower := strings.ToLower(content)
	for _, placeholder := range []string{
		"path/to/file.go",
		"symbolname",
		"describe the requirements-driven implementation scope",
		"describe the packages, commands, boundaries, configuration, and tests inspected",
		"explain why this source reference is relevant",
		"describe how the selected code collaborates",
		"record implementation constraints and invariants",
		"record remaining source-level questions",
	} {
		if strings.Contains(lower, placeholder) {
			return true
		}
	}
	return false
}

type codeContextEntry struct{ name, body string }

func codeContextEntries(section string) []codeContextEntry {
	matches := codeContextEntryRE.FindAllStringSubmatchIndex(section, -1)
	out := make([]codeContextEntry, 0, len(matches))
	for i, match := range matches {
		end := len(section)
		if i+1 < len(matches) {
			end = matches[i+1][0]
		}
		out = append(out, codeContextEntry{name: strings.TrimSpace(section[match[2]:match[3]]), body: section[match[1]:end]})
	}
	return out
}

func sectionBody(content, heading string) string {
	matches := codeContextHeadingRE.FindAllStringSubmatchIndex(content, -1)
	for i, match := range matches {
		if !strings.EqualFold(strings.TrimSpace(content[match[2]:match[3]]), heading) {
			continue
		}
		end := len(content)
		if i+1 < len(matches) {
			end = matches[i+1][0]
		}
		return content[match[1]:end]
	}
	return ""
}

func validateRepositoryRelativePath(value string) error {
	value = strings.Trim(strings.TrimSpace(value), "`")
	if value == "" || filepath.IsAbs(value) || strings.Contains(value, `\`) || codeContextDriveRE.MatchString(value) {
		return fmt.Errorf("path must be non-empty and relative")
	}
	clean := filepath.ToSlash(filepath.Clean(filepath.FromSlash(value)))
	if clean == "." || clean == ".." || strings.HasPrefix(clean, "../") || strings.ContainsAny(value, "\x00\r\n") {
		return fmt.Errorf("path escapes or does not identify a source file")
	}
	return nil
}

func validateLineRange(value string) error {
	value = strings.Trim(strings.TrimSpace(value), "`")
	if value == "" {
		return fmt.Errorf("range must contain at least one positive line number")
	}
	for _, segment := range strings.Split(value, ",") {
		if err := validateSingleLineRange(strings.TrimSpace(segment)); err != nil {
			return err
		}
	}
	return nil
}

func validateSingleLineRange(value string) error {
	parts := strings.Split(value, "-")
	if len(parts) < 1 || len(parts) > 2 {
		return fmt.Errorf("range %q must be N or N-M", value)
	}
	start, err := strconv.Atoi(strings.TrimSpace(parts[0]))
	if err != nil || start < 1 {
		return fmt.Errorf("range %q has an invalid start", value)
	}
	if len(parts) == 2 {
		end, err := strconv.Atoi(strings.TrimSpace(parts[1]))
		if err != nil || end < start {
			return fmt.Errorf("range %q has an invalid end", value)
		}
	}
	return nil
}

func (s Service) PromptCodeContext(projectRef, sprintRef string) (PromptPreview, error) {
	sp, inputs, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return PromptPreview{}, err
	}
	if findings := ValidateRequirementsContent(inputs.Requirements); len(findings) > 0 {
		return PromptPreview{}, fmt.Errorf("code-context prerequisites failed validation")
	}
	target, findings := s.resolveSprintTarget(sp, inputs.ProjectIndex, false)
	if len(findings) > 0 {
		return PromptPreview{}, fmt.Errorf("code-context target resolution failed: %s", formatValidationFindings(findings))
	}
	return RenderCodeContextPrompt(s.root, sp, inputs.Requirements, target), nil
}

func (s Service) ValidateCodeContext(projectRef, sprintRef string) (ValidationResult, error) {
	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return ValidationResult{}, err
	}
	path := mustArtifactPath(s.root, sp, StageCodeContext)
	data, readErr := s.store.ReadArtifact(sp, StageCodeContext)
	var findings []ValidationFinding
	if readErr != nil {
		findings = []ValidationFinding{finding("code-context.md", "", workspace.Rel(s.root, path), "missing code context", readErr.Error(), "Run the code-context stage after requirements validate.")}
	} else {
		findings = ValidateCodeContextContent(data)
	}
	return ValidationResult{Project: sp.Project, Sprint: sp.Slug, Artifact: workspace.Rel(s.root, path), Findings: findings}, nil
}

func (s Service) codeContextPrerequisite(sp Sprint) ([]ValidationFinding, error) {
	validation, err := s.ValidateCodeContext(sp.Project, sp.Slug)
	if err != nil {
		return nil, err
	}
	if !validation.Valid() {
		return validation.Findings, fmt.Errorf("code-context prerequisite failed validation")
	}
	state, err := LoadFlowState(s.root, sp)
	if err != nil {
		return validation.Findings, fmt.Errorf("code-context prerequisite has no successful persisted outcome: %w", err)
	}
	for _, stage := range state.Stages {
		if stage.Stage == StageCodeContext && stage.Status == StatusComplete {
			return nil, nil
		}
	}
	return validation.Findings, fmt.Errorf("code-context prerequisite has not completed successfully")
}

func (s Service) FlowCodeContext(ctx context.Context, projectRef, sprintRef string, req FlowRequest) (FlowResult, error) {
	if req.To != StageCodeContext {
		return FlowResult{}, fmt.Errorf("unsupported code-context flow target %q", req.To)
	}
	sp, inputs, _, err := s.resolveSprintInputsForFlow(projectRef, sprintRef, !req.DryRun)
	if err != nil {
		return FlowResult{}, err
	}
	now := s.now().UTC()
	if findings := ValidateRequirementsContent(inputs.Requirements); len(findings) > 0 {
		err := fmt.Errorf("code-context prerequisites failed validation")
		return s.failCodeContext(sp, req, now, pruntime.Result{}, findings, err)
	}
	target, findings := s.resolveSprintTarget(sp, inputs.ProjectIndex, !req.DryRun)
	if len(findings) > 0 {
		err := fmt.Errorf("code-context target resolution failed")
		return s.failCodeContext(sp, req, now, pruntime.Result{}, findings, err)
	}
	prompt := RenderCodeContextPrompt(s.root, sp, inputs.Requirements, target)
	if req.DryRun {
		return FlowResult{Project: sp.Project, Sprint: sp.Slug, To: req.To, DryRun: true, Message: prompt.Prompt}, nil
	}
	if s.runtime == nil {
		return s.failCodeContext(sp, req, now, pruntime.Result{}, nil, fmt.Errorf("runtime is required for code-context flow"))
	}
	candidate, err := os.CreateTemp(sp.Path, ".code-context.*.candidate.md")
	if err != nil {
		return s.failCodeContext(sp, req, now, pruntime.Result{}, nil, fmt.Errorf("create code-context candidate: %w", err))
	}
	candidatePath := candidate.Name()
	if err := candidate.Close(); err != nil {
		_ = os.Remove(candidatePath)
		return s.failCodeContext(sp, req, now, pruntime.Result{}, nil, fmt.Errorf("close code-context candidate: %w", err))
	}
	defer os.Remove(candidatePath)
	runtimeReq := s.runtimeRequest(prompt.Prompt, map[string]string{"project": sp.Project, "sprint": sp.Slug, "stage": string(StageCodeContext), "output_path": ArtifactRelPath(sp, StageCodeContext), "candidate_path": candidatePath, "target_source": target.Source})
	if strings.TrimSpace(req.ModelOverride) != "" {
		runtimeReq.Provider, runtimeReq.Model = splitProviderModel(strings.TrimSpace(req.ModelOverride))
		runtimeReq.Metadata["model_source"] = "command override"
	} else {
		runtimeReq.Metadata["model_source"] = "effective configuration"
	}
	if strings.TrimSpace(req.VariantOverride) != "" {
		runtimeReq.Metadata["variant"] = strings.TrimSpace(req.VariantOverride)
		runtimeReq.Metadata["reasoning_effort"] = strings.TrimSpace(req.VariantOverride)
		runtimeReq.Metadata["variant_source"] = "command override"
	} else {
		runtimeReq.Metadata["variant_source"] = "effective configuration"
	}
	runtimeReq.WorkDir = target.Path
	runtimeReq.Sandbox = "read_only"
	runtimeReq.Permissions = "restricted"
	runtimeReq.Policy = pruntime.PermissionPolicy{Default: "deny", Tools: map[string]string{"read": "allow", "glob": "allow", "search": "allow", "list": "allow"}}
	runtimeReq.RequireCaps = appendUniqueString(runtimeReq.RequireCaps, "permissions")
	result, runErr := s.startPlanningStageRun(ctx, sp, StageCodeContext, runtimeReq)
	if runErr != nil {
		return s.failCodeContext(sp, req, now, result, validateCodeContextResult(result), runErr)
	}
	if err := ctx.Err(); err != nil {
		return s.failCodeContext(sp, req, now, result, nil, err)
	}
	if result.Permissions.UnsupportedCount > 0 {
		return s.failCodeContext(sp, req, now, result, nil, fmt.Errorf("runtime cannot enforce required code-context read-only permission policy"))
	}
	if status := strings.ToLower(strings.TrimSpace(result.Status)); status != "" && status != "success" && status != "complete" && status != "completed" {
		return s.failCodeContext(sp, req, now, result, nil, fmt.Errorf("code-context runtime ended with status %q", result.Status))
	}
	content := codeContextResultContent(result)
	findings = ValidateCodeContextContent(content)
	findings = append(findings, validateResolvedCodeContext(ctx, sp, inputs.Requirements, content, target.Path)...)
	sortSprintFindings(findings)
	result.Validation = pruntime.ValidationSummary{Configured: true, Passed: len(findings) == 0, Failures: len(findings)}
	result.Repair = pruntime.RepairSummary{Configured: true, MaxAttempts: generatedArtifactRepairAttempts}
	if len(findings) > 0 && result.SessionID != "" {
		repairReq := runtimeReq
		repairReq.Prompt = buildCodeContextRepairPrompt(ArtifactRelPath(sp, StageCodeContext), findings)
		repairReq.SessionID = result.SessionID
		repairReq.SessionAction = "continue"
		repairReq.Metadata = cloneMetadata(repairReq.Metadata, map[string]string{"repair": "validation", "repair_artifact": ArtifactRelPath(sp, StageCodeContext)})
		repaired, repairErr := s.startSprintRuntime(ctx, sp, StageCodeContext, repairReq)
		repaired.Repair = pruntime.RepairSummary{Configured: true, Attempted: true, MaxAttempts: generatedArtifactRepairAttempts, AttemptCount: 1}
		if repairErr != nil {
			return s.failCodeContext(sp, req, now, repaired, findings, repairErr)
		}
		if err := codeContextRuntimeResultError(repaired); err != nil {
			return s.failCodeContext(sp, req, now, repaired, nil, err)
		}
		result = repaired
		content = codeContextResultContent(result)
		findings = ValidateCodeContextContent(content)
		findings = append(findings, validateResolvedCodeContext(ctx, sp, inputs.Requirements, content, target.Path)...)
		sortSprintFindings(findings)
		result.Validation = pruntime.ValidationSummary{Configured: true, Passed: len(findings) == 0, Failures: len(findings)}
		if len(findings) > 0 {
			result.Repair.Exhausted = true
			result.Repair.ExhaustedReason = "validation findings remain after the bounded repair attempt"
		}
	}
	if content != "" {
		if err := os.WriteFile(candidatePath, []byte(content+"\n"), 0o644); err != nil {
			return s.failCodeContext(sp, req, now, result, nil, fmt.Errorf("write code-context candidate: %w", err))
		}
	}
	data, readErr := os.ReadFile(candidatePath)
	if readErr != nil || len(strings.TrimSpace(string(data))) == 0 {
		if readErr == nil {
			readErr = errors.New("runtime returned no code-context output")
		}
		return s.failCodeContext(sp, req, now, result, nil, readErr)
	}
	findings = ValidateCodeContextContent(string(data))
	findings = append(findings, validateResolvedCodeContext(ctx, sp, inputs.Requirements, string(data), target.Path)...)
	sortSprintFindings(findings)
	if len(findings) > 0 {
		return s.failCodeContext(sp, req, now, result, findings, fmt.Errorf("generated code-context.md failed validation"))
	}
	if err := os.Chmod(candidatePath, 0o644); err != nil {
		return s.failCodeContext(sp, req, now, result, nil, fmt.Errorf("set code-context candidate permissions: %w", err))
	}
	stages := flowCodeContextSuccessStages(sp, now)
	prefix, prefixErr := renderSharedPromptContext(ctx, sp, inputs.Requirements, string(data), target.Path)
	if prefixErr != nil {
		return s.failCodeContext(sp, req, now, result, nil, prefixErr)
	}
	// Best effort only: the pack is derived and live resolution remains the
	// authoritative fallback.
	_ = saveContextPack(s.root, sp, inputs.Requirements, string(data), target.Path, prefix, now)
	if err := s.promoteCodeContext(ctx, sp, candidatePath, NewFlowState(sp, stages, now)); err != nil {
		return s.failCodeContext(sp, req, now, result, nil, err)
	}
	_ = s.cleanupPlanningStageSessions(ctx, sp, StageCodeContext, result)
	return FlowResult{Project: sp.Project, Sprint: sp.Slug, To: req.To, Runtime: result, Stages: stages, Message: "code-context complete"}, nil
}

func validateResolvedCodeContext(ctx context.Context, sp Sprint, requirements, content, target string) []ValidationFinding {
	if len(ValidateCodeContextContent(content)) > 0 {
		return nil
	}
	if _, err := renderSharedPromptContext(ctx, sp, requirements, content, target); err != nil {
		return []ValidationFinding{finding("Selected Source References", "resolved context", ArtifactRelPath(sp, StageCodeContext), "source context cannot be prepared", err.Error(), "Correct missing, excessive, or out-of-range source references and retry code-context generation.")}
	}
	return nil
}

func codeContextResultContent(result pruntime.Result) string {
	content := strings.TrimSpace(result.TerminalOutput)
	if content == "" {
		content = strings.TrimSpace(runtimeEventContent(result.Events))
	}
	return content
}

func validateCodeContextResult(result pruntime.Result) []ValidationFinding {
	content := codeContextResultContent(result)
	if content == "" {
		return nil
	}
	return ValidateCodeContextContent(content)
}

func codeContextRuntimeResultError(result pruntime.Result) error {
	if result.Permissions.UnsupportedCount > 0 {
		return fmt.Errorf("runtime cannot enforce required code-context read-only permission policy")
	}
	if status := strings.ToLower(strings.TrimSpace(result.Status)); status != "" && status != "success" && status != "complete" && status != "completed" {
		return fmt.Errorf("code-context runtime ended with status %q", result.Status)
	}
	return nil
}

func (s Service) failCodeContext(sp Sprint, req FlowRequest, now time.Time, result pruntime.Result, findings []ValidationFinding, err error) (FlowResult, error) {
	stages := s.flowFailedStages(sp, StageCodeContext, err, now)
	for i := range stages {
		if stages[i].Stage == StageCodeContext {
			stages[i].LatestOutcome = codeContextLatestOutcome(result, err)
			break
		}
	}
	if !req.DryRun {
		if saveErr := SaveFlowState(s.root, sp, NewFlowState(sp, stages, now)); saveErr != nil {
			err = errors.Join(err, fmt.Errorf("persist failed code-context outcome: %w", saveErr))
		}
	}
	return FlowResult{Project: sp.Project, Sprint: sp.Slug, To: req.To, DryRun: req.DryRun, Runtime: result, Stages: stages, Findings: findings}, err
}

func codeContextLatestOutcome(result pruntime.Result, err error) string {
	if result.Cleanup.Failed || (result.Cleanup.Attempted && !result.Cleanup.Completed) {
		return "cleanup_uncertain"
	}
	status := strings.ToLower(strings.TrimSpace(result.Status))
	if errors.Is(err, context.Canceled) || status == "cancelled" || status == "canceled" {
		return "cancelled"
	}
	if status == "interrupted" {
		return "interrupted"
	}
	return "failed"
}

func (s Service) promoteCodeContext(ctx context.Context, sp Sprint, candidatePath string, state FlowState) error {
	finalPath, err := ArtifactPath(s.root, sp, StageCodeContext)
	if err != nil {
		return err
	}
	old, oldErr := os.ReadFile(finalPath)
	oldExists := oldErr == nil
	if oldErr != nil && !os.IsNotExist(oldErr) {
		return fmt.Errorf("read prior code-context artifact: %w", oldErr)
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if err := os.Rename(candidatePath, finalPath); err != nil {
		return fmt.Errorf("promote code-context artifact: %w", err)
	}
	persistErr := ctx.Err()
	if persistErr == nil {
		persistErr = SaveFlowState(s.root, sp, state)
	}
	if persistErr != nil {
		if oldExists {
			restore, restoreErr := os.CreateTemp(sp.Path, ".code-context.*.restore.md")
			if restoreErr == nil {
				_, restoreErr = restore.Write(old)
				if restoreErr == nil {
					restoreErr = restore.Sync()
				}
				if closeErr := restore.Close(); restoreErr == nil {
					restoreErr = closeErr
				}
				if restoreErr == nil {
					restoreErr = os.Rename(restore.Name(), finalPath)
				}
				if restoreErr != nil {
					_ = os.Remove(restore.Name())
				}
			}
			if restoreErr != nil {
				return fmt.Errorf("persist code-context state: %v; restore prior artifact: %w", persistErr, restoreErr)
			}
		} else {
			_ = os.Remove(finalPath)
		}
		syncDir(sp.Path)
		return fmt.Errorf("persist code-context state: %w", persistErr)
	}
	syncDir(sp.Path)
	return nil
}

func appendUniqueString(values []string, value string) []string {
	for _, current := range values {
		if current == value {
			return values
		}
	}
	return append(values, value)
}

func runtimeEventContent(events []pruntime.Event) string {
	for i := len(events) - 1; i >= 0; i-- {
		for _, key := range []string{"content", "text", "output"} {
			if value, ok := events[i].Payload[key].(string); ok && strings.TrimSpace(value) != "" {
				return value
			}
		}
	}
	return ""
}

package sprint

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	pruntime "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
)

const stageSessionSchemaVersion = 1

type stageSessionRecord struct {
	SessionID      string    `json:"sessionId"`
	Provider       string    `json:"provider,omitempty"`
	Model          string    `json:"model,omitempty"`
	WorkDir        string    `json:"workDir"`
	PromptChecksum string    `json:"promptChecksum,omitempty"`
	UpdatedAt      time.Time `json:"updatedAt"`
}

type stageSessionState struct {
	SchemaVersion int                           `json:"schemaVersion"`
	Sessions      map[string]stageSessionRecord `json:"sessions"`
}

func stageSessionPath(sp Sprint) string { return filepath.Join(sp.Path, ".stage-sessions.json") }

func loadStageSessions(sp Sprint) (stageSessionState, error) {
	path := stageSessionPath(sp)
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return stageSessionState{SchemaVersion: stageSessionSchemaVersion, Sessions: map[string]stageSessionRecord{}}, nil
	}
	if err != nil {
		return stageSessionState{}, err
	}
	var state stageSessionState
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&state); err != nil {
		return stageSessionState{}, fmt.Errorf("decode stage sessions: %w", err)
	}
	var trailing any
	if err := dec.Decode(&trailing); !errors.Is(err, io.EOF) {
		return stageSessionState{}, fmt.Errorf("decode stage sessions: trailing JSON")
	}
	if state.SchemaVersion != stageSessionSchemaVersion || state.Sessions == nil {
		return stageSessionState{}, fmt.Errorf("unsupported stage session state")
	}
	return state, nil
}

func saveStageSessions(sp Sprint, state stageSessionState) error {
	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	path := stageSessionPath(sp)
	tmp, err := os.CreateTemp(sp.Path, ".stage-sessions.*.tmp")
	if err != nil {
		return err
	}
	tmpPath := tmp.Name()
	defer os.Remove(tmpPath)
	if _, err = tmp.Write(data); err == nil {
		err = tmp.Chmod(0o600)
	}
	if closeErr := tmp.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return err
	}
	return os.Rename(tmpPath, path)
}

func stageSessionCompatible(record stageSessionRecord, req pruntime.Request) bool {
	// Prompt checksums are retained for diagnostics only. Exact prompt matching
	// would make interrupted-session recovery brittle after harmless artifact
	// edits; the continuation explicitly tells the agent to reread current state.
	return record.SessionID != "" && record.Provider == req.Provider && record.Model == req.Model && record.WorkDir == req.WorkDir
}

func stageSessionKey(stage PlanningStage, req pruntime.Request) string {
	parts := []string{string(stage)}
	for _, dimension := range []string{"task", "coverage", "area"} {
		parts = append(parts, strings.TrimSpace(req.Metadata[dimension]))
	}
	if parts[1] == "" && parts[2] == "" && parts[3] == "" {
		return parts[0]
	}
	return strings.Join(parts, ":")
}

func (s Service) startPlanningStageRun(ctx context.Context, sp Sprint, stage PlanningStage, req pruntime.Request) (pruntime.Result, error) {
	key := stageSessionKey(stage, req)
	originalPrompt := req.Prompt
	continuing := false
	state, loadErr := loadStageSessions(sp)
	if loadErr == nil {
		if record, ok := state.Sessions[key]; ok && stageSessionCompatible(record, req) {
			req.SessionID = record.SessionID
			req.SessionAction = "continue"
			req.Prompt = insertStageContinuation(req.Prompt, "Continue the interrupted UltraPlan stage from the existing session. Re-read the current stage prompt and filesystem state, then finish only the requested stage.")
			continuing = true
		}
	}
	previousOnEvent := req.OnEvent
	var mu sync.Mutex
	lastSession := req.SessionID
	persist := func(sessionID string) {
		if strings.TrimSpace(sessionID) == "" {
			return
		}
		mu.Lock()
		defer mu.Unlock()
		if sessionID == lastSession {
			return
		}
		lastSession = sessionID
		current, err := loadStageSessions(sp)
		if err != nil {
			return
		}
		current.Sessions[key] = stageSessionRecord{SessionID: sessionID, Provider: req.Provider, Model: req.Model, WorkDir: req.WorkDir, PromptChecksum: req.PromptRef.Checksum, UpdatedAt: s.now().UTC()}
		_ = saveStageSessions(sp, current)
	}
	req.OnEvent = func(event pruntime.Event) {
		if previousOnEvent != nil {
			previousOnEvent(event)
		}
		persist(event.SessionID)
	}
	result, err := s.startSprintRuntime(ctx, sp, stage, req)
	persist(result.SessionID)
	if continuing && planningSessionNotFound(result, err) && ctx.Err() == nil {
		_ = clearPlanningStageSessionKey(sp, key)
		lastSession = ""
		req.SessionID = ""
		req.SessionAction = "fresh"
		req.Prompt = originalPrompt
		result, err = s.startSprintRuntime(ctx, sp, stage, req)
		persist(result.SessionID)
	}
	return result, err
}

func planningSessionNotFound(result pruntime.Result, err error) bool {
	var details []string
	if err != nil {
		details = append(details, err.Error())
	}
	details = append(details, result.TerminalOutput)
	if result.Error != nil {
		details = append(details, result.Error.UserDetail, result.Error.DebugDetail)
	}
	for _, attempt := range result.Attempts {
		details = append(details, attempt.ErrorDetail)
	}
	return strings.Contains(strings.ToLower(strings.Join(details, "\n")), "session not found")
}

func insertStageContinuation(prompt, instruction string) string {
	boundary := strings.Index(prompt, sharedPromptStageBoundary)
	if boundary < 0 {
		return instruction + "\n\n" + prompt
	}
	boundary += len(sharedPromptStageBoundary)
	return prompt[:boundary] + instruction + "\n\n" + prompt[boundary:]
}

func clearPlanningStageSession(sp Sprint, stage PlanningStage) error {
	state, err := loadStageSessions(sp)
	if err != nil {
		return err
	}
	found := false
	for key := range state.Sessions {
		if key == string(stage) || strings.HasPrefix(key, string(stage)+":") {
			delete(state.Sessions, key)
			found = true
		}
	}
	if !found {
		return nil
	}
	return saveOrRemoveStageSessions(sp, state)
}

func clearPlanningStageSessionKey(sp Sprint, key string) error {
	state, err := loadStageSessions(sp)
	if err != nil {
		return err
	}
	if _, ok := state.Sessions[key]; !ok {
		return nil
	}
	delete(state.Sessions, key)
	return saveOrRemoveStageSessions(sp, state)
}

func saveOrRemoveStageSessions(sp Sprint, state stageSessionState) error {
	if len(state.Sessions) == 0 {
		if err := os.Remove(stageSessionPath(sp)); err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
		return nil
	}
	return saveStageSessions(sp, state)
}

func (s Service) cleanupPlanningStageSession(ctx context.Context, sp Sprint, stage PlanningStage, sessionID string) error {
	if err := s.deleteCompletedSession(ctx, sessionID); err != nil {
		return err
	}
	return clearPlanningStageSession(sp, stage)
}

func (s Service) cleanupPlanningStageSessions(ctx context.Context, sp Sprint, stage PlanningStage, result pruntime.Result) error {
	if err := s.deleteCompletedSessions(ctx, result); err != nil {
		return err
	}
	return clearPlanningStageSession(sp, stage)
}

package sprint

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/gitpublish"
	pprocess "github.com/Antonio7098/ultraplan-go/internal/platform/process"
	pruntime "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/project"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

type Service struct {
	root                string
	store               FSStore
	now                 func() time.Time
	runtime             Runtime
	runtimeConfig       pruntime.Request
	runtimeProgress     func(RuntimeProgress)
	stageRuntime        map[PlanningStage]StageRuntime
	verificationRuntime map[VerificationPhase]StageRuntime
	qaSettings          QASettings
	qaSettingsErr       error
	qaWriterFence       func(QAWriterToken) error
	qaMapFence          func(QAMap) error
	reviewConcurrency   int
	processRunner       pprocess.Runner
	smokeSettings       SmokeSettings
	mutations           *sync.Map
	metricsMu           *sync.Mutex
	statusWrites        bool
	codeContextTarget   func(string) (ExecuteTargetRef, []ValidationFinding)
	publisher           gitpublish.Publisher
}

func (s Service) WithReviewConcurrency(n int) Service { s.reviewConcurrency = n; return s }

// WithClock supplies a deterministic clock for state-transition tests.
func (s Service) WithClock(now func() time.Time) Service {
	if now != nil {
		s.now = now
	}
	return s
}

func (s Service) WithProcessRunner(runner pprocess.Runner) Service {
	s.processRunner = runner
	return s
}

func (s Service) WithPublisher(publisher gitpublish.Publisher) Service {
	s.publisher = publisher
	return s
}

func (s Service) WithSmokeSettings(settings SmokeSettings) Service {
	s.smokeSettings = settings
	return s
}

type StageRuntime struct {
	Model   string
	Variant string
}

func NewService(root string) Service {
	return Service{root: root, store: NewFSStore(root), now: func() time.Time { return time.Now().UTC() }, processRunner: pprocess.DirectRunner{}, smokeSettings: DefaultSmokeSettings(), mutations: &sync.Map{}, metricsMu: &sync.Mutex{}, statusWrites: true}
}

// WithoutStatusWrites derives status from current artifacts without creating a
// missing flow-state file. It is used by strictly read-only presentation
// surfaces; existing CLI/TUI status behavior remains unchanged.
func (s Service) WithoutStatusWrites() Service {
	s.statusWrites = false
	return s
}

var ErrVerificationConflict = errors.New("verification mutation already in progress")

func (s Service) acquireMutation(projectRef, sprintRef string) (func(), error) {
	sp, err := s.resolveMutationSprint(projectRef, sprintRef)
	if err != nil {
		return nil, err
	}
	key := filepath.Clean(sp.Path)
	if s.mutations == nil {
		s.mutations = &sync.Map{}
	}
	if _, loaded := s.mutations.LoadOrStore(key, struct{}{}); loaded {
		return nil, fmt.Errorf("%w for %s/%s; wait for the active attempt or cancel it", ErrVerificationConflict, sp.Project, sp.Slug)
	}
	fileLock, lockErr := acquireVerificationFileLock(s.root, sp, s.now().UTC())
	if lockErr != nil {
		s.mutations.Delete(key)
		return nil, lockErr
	}
	return func() {
		_ = fileLock.release()
		s.mutations.Delete(key)
	}, nil
}

func (s Service) WithRuntime(rt Runtime, reqs ...pruntime.Request) Service {
	s.runtime = rt
	if len(reqs) > 0 {
		s.runtimeConfig = reqs[0]
	}
	return s
}

type RuntimeProgress struct {
	Stage      PlanningStage
	Task       string
	CoverageID string
	Event      pruntime.Event
}

// WithRuntimeProgress observes bounded, sanitized runtime events for every
// runtime-backed sprint operation created by this service.
func (s Service) WithRuntimeProgress(progress func(RuntimeProgress)) Service {
	s.runtimeProgress = progress
	return s
}

func (s Service) WithStageRuntime(overrides map[PlanningStage]StageRuntime) Service {
	s.stageRuntime = map[PlanningStage]StageRuntime{}
	if s.verificationRuntime == nil {
		s.verificationRuntime = map[VerificationPhase]StageRuntime{}
	}
	for stage, override := range overrides {
		if phase, ok := verificationPhaseForStage(stage); ok {
			s.verificationRuntime[phase] = override
			continue
		}
		s.stageRuntime[stage] = override
	}
	return s
}

func (s Service) WithVerificationRuntime(overrides map[VerificationPhase]StageRuntime) Service {
	s.verificationRuntime = make(map[VerificationPhase]StageRuntime, len(overrides))
	for phase, override := range overrides {
		s.verificationRuntime[phase] = override
	}
	return s
}

// WithQASettings freezes the validated effective QA policy on the service
// value. It does not construct a runtime, acquire ownership, or write state.
func (s Service) WithQASettings(settings QASettings) Service {
	s.qaSettings = settings
	s.qaSettingsErr = ValidateQASettings(settings)
	return s
}

// WithQAWriterFence installs the durable run-ownership check used before each
// QA publication. Callers that own run control should compare all token fields
// against the currently claimed operation.
func (s Service) WithQAWriterFence(fence func(QAWriterToken) error) Service {
	s.qaWriterFence = fence
	return s
}

// WithQAMapFence installs the governed-input check used immediately before
// investigator work and publication. Production callers normally use the
// service's deterministic map rebuild; tests and alternate stores can supply
// the same boundary without mutating Service internals.
func (s Service) WithQAMapFence(fence func(QAMap) error) Service {
	s.qaMapFence = fence
	return s
}

func (s Service) effectiveQASettings() (QASettings, error) {
	if s.qaSettingsErr != nil {
		return QASettings{}, s.qaSettingsErr
	}
	if strings.TrimSpace(s.qaSettings.Runtime.Model) == "" {
		return QASettings{}, fmt.Errorf("QA settings are not configured")
	}
	return s.qaSettings, nil
}

// withStageOverrides returns a service copy whose stage runtime map is merged
// with request-scoped stage model/variant overrides. Configured defaults stay
// unchanged for stages without an entry.
func (s Service) withStageOverrides(overrides map[PlanningStage]StageRuntime) Service {
	if len(overrides) == 0 {
		return s
	}
	merged := make(map[PlanningStage]StageRuntime, len(s.stageRuntime)+len(overrides))
	for stage, override := range s.stageRuntime {
		merged[stage] = override
	}
	for stage, override := range overrides {
		if override.Model == "" && override.Variant == "" {
			continue
		}
		current := merged[stage]
		if override.Model != "" {
			current.Model = override.Model
		}
		if override.Variant != "" {
			current.Variant = override.Variant
		}
		merged[stage] = current
	}
	s.stageRuntime = merged
	return s
}

func (s Service) runtimeForStage(stage PlanningStage) (StageRuntime, bool) {
	if phase, ok := verificationPhaseForStage(stage); ok {
		runtime, found := s.verificationRuntime[phase]
		return runtime, found
	}
	runtime, found := s.stageRuntime[stage]
	return runtime, found
}

func (s Service) Status(projectRef, sprintRef string) (StatusSummary, error) {
	projects, err := project.DiscoverProjects(s.root)
	if err != nil {
		return StatusSummary{}, err
	}
	p, err := project.ResolveProject(projects, projectRef)
	if err != nil {
		return StatusSummary{}, err
	}
	sprints, err := DiscoverSprints(s.root, p)
	if err != nil {
		return StatusSummary{}, err
	}
	sp, err := ResolveSprint(sprints, sprintRef)
	if err != nil {
		return StatusSummary{}, err
	}
	if !inside(p.Path, sp.Path) {
		return StatusSummary{}, fmt.Errorf("sprint path mismatch for %q", sp.Slug)
	}
	legacyCodeContextState := preCodeContextFlowState(s.root, sp)
	state, err := LoadFlowState(s.root, sp)
	stateLoaded := err == nil
	if err != nil && !errors.Is(err, ErrFlowStateMissing) {
		return StatusSummary{}, err
	}
	snap, err := s.store.ReadArtifacts(sp)
	if err != nil {
		return StatusSummary{}, err
	}
	var prior []StageState
	if stateLoaded {
		prior = state.Stages
	}
	stages := DeriveStages(sp, snap, prior)
	refreshed := NewFlowState(sp, stages, s.now())
	if stateLoaded {
		refreshed.Review = state.Review
		refreshed.Smoke = state.Smoke
		refreshed.QA = state.QA
		if refreshed.Review != nil && refreshed.Review.Fingerprint != "" {
			manifest, reviewFindings, reviewErr := s.PrepareReview(projectRef, sprintRef, ReviewRequest{})
			refreshed.Review.Stale = reviewErr != nil || len(reviewFindings) > 0 || (strictCompletedReviewSnapshotFreshness && manifest.Fingerprint != refreshed.Review.Fingerprint)
			if !refreshed.Review.Stale {
				content, readErr := s.store.ReadArtifact(sp, StageReview)
				validationManifest := manifest
				if !strictCompletedReviewSnapshotFreshness {
					validationManifest.Fingerprint = refreshed.Review.Fingerprint
				}
				refreshed.Review.Stale = readErr != nil || len(ValidateReviewContent(content, validationManifest)) > 0 || refreshed.Review.ArtifactDigest == "" || hashBytes([]byte(content)) != refreshed.Review.ArtifactDigest
			}
		}
		if refreshed.Smoke != nil {
			smokePath, pathErr := ArtifactPath(s.root, sp, StageSmoke)
			data, readErr := os.ReadFile(smokePath)
			invalid := pathErr != nil || readErr != nil || len(ValidateSmokeContent(string(data))) > 0
			fingerprintMismatch := readErr == nil && refreshed.Smoke.SmokeFingerprint != "" && refreshed.Smoke.SmokeFingerprint != hashBytes(data)
			reviewMismatch := refreshed.Review == nil || refreshed.Review.Stale || refreshed.Smoke.ReviewFingerprint != refreshed.Review.Fingerprint
			refreshed.Smoke.Stale = invalid || fingerprintMismatch || reviewMismatch
			refreshed.Smoke.Reconciliation = fingerprintMismatch || (readErr == nil && refreshed.Smoke.SmokeFingerprint == "")
		}
	}
	if s.statusWrites && !legacyCodeContextState {
		if err := SaveFlowState(s.root, sp, refreshed); err != nil {
			return StatusSummary{}, err
		}
	}
	flowPath, err := FlowStatePath(s.root, sp)
	if err != nil {
		return StatusSummary{}, err
	}
	var executeState *ExecuteRunState
	var historicalExecutionStatus string
	loadedExecute, executeErr := LoadExecuteRunState(s.root, sp)
	if executeErr != nil && !errors.Is(executeErr, ErrExecuteRunStateMissing) {
		if legacyStatus, ok := LegacyTerminalExecuteStatus(s.root, sp); ok {
			historicalExecutionStatus = legacyStatus
		} else {
			return StatusSummary{}, executeErr
		}
	}
	if executeErr == nil {
		executeState = &loadedExecute
	}
	runStatePath, err := ExecuteRunStatePath(s.root, sp)
	if err != nil {
		return StatusSummary{}, err
	}
	verification := VerificationStatus{Project: sp.Project, Sprint: sp.Slug}
	if historicalExecutionStatus == "" {
		var verificationErr error
		verification, verificationErr = s.VerificationStatus(projectRef, sprintRef)
		if verificationErr != nil && !errors.Is(verificationErr, ErrFlowStateMissing) {
			return StatusSummary{}, verificationErr
		}
	} else {
		verification.Assessment = AssessmentNotApplicable
		verification.NextAction = "Historical terminal execution evidence is preserved; modern review and smoke evidence is not available."
	}
	return StatusSummary{
		Project:                   sp.Project,
		Sprint:                    sp.Slug,
		SprintRoot:                workspace.Rel(s.root, sp.Path),
		FlowStatePath:             workspace.Rel(s.root, flowPath),
		Stages:                    stages,
		ExecuteState:              executeState,
		HistoricalExecutionStatus: historicalExecutionStatus,
		ExecutePath:               ArtifactRelPath(sp, StageExecute),
		RunStatePath:              workspace.Rel(s.root, runStatePath),
		Review:                    refreshed.Review,
		ReviewPath:                ArtifactRelPath(sp, StageReview),
		Smoke:                     refreshed.Smoke,
		SmokePath:                 ArtifactRelPath(sp, StageSmoke),
		QA:                        refreshed.QA,
		Verification:              verification,
	}, nil
}

