cat > internal/sprint/zz_gauntlet_boundary_test.go <<'EOF'
package sprint

import (
	"strings"
	"testing"
)

func TestGauntletBoundaryExactArtifactFailsAfterNewlineAppend(t *testing.T) {
	base := validCodeContext()
	padding := maxCodeContextBytes - len(base) - 1 // final newline will re-add 1
	if padding < 0 {
		t.Fatalf("fixture too large: %d", len(base))
	}
	content := strings.Replace(base, "Add the selected stage.", "Add the selected stage."+strings.Repeat("x", padding), 1)
	if len(content) != maxCodeContextBytes {
		t.Fatalf("length=%d want=%d", len(content), maxCodeContextBytes)
	}
	if findings := ValidateCodeContextContent(content); len(findings) != 0 {
		t.Fatalf("pre-write validation failed: %+v", findings)
	}
	findings := ValidateCodeContextContent(content + "\n")
	if len(findings) == 0 {
		t.Fatal("newline-appended artifact unexpectedly still valid")
	}
	if findings[0].Problem != "code context exceeds the output budget" {
		t.Fatalf("unexpected finding: %+v", findings[0])
	}
}
EOF
go test ./internal/sprint -run 'TestGauntletBoundary' -count=1 -v 2>&1 | tail -8; rm internal/sprint/zz_gauntlet_boundary_test.go

